contract InvMutTest {
    C c;

    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 guessHash) public payable {
        bool settledNow;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            settledNow = false;
        } else {
            settledNow = true;
        }

        assert(!settledNow);
    }

    receive() external payable {}
}

