pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 guessHash) internal {
        bool settledNow;
        try c.settle() {
            settledNow = true;
        } catch {
            settledNow = false;
        }
        assertTrue(!settledNow);
    }

    function testFuzz_run(bytes32 guessHash) public {
        _run(guessHash);
    }

    receive() external payable {}
}
